CREATE   VIEW [Expenses].[vwTravelExpenses_Full]
AS
	SELECT
		[Company Name],
		[Point of Sale Country],
		[Cost Center],
		[Department1] AS [Department],
		[Department] AS [Business Unit],
		[Directorate],
		[Employee ID],
		[Reason for Travel],
		[Is Guest Traveler],
		[Traveller Email],
		[Traveller Group],
		[Traveller Name],
		[Invoice Date],
		[Transaction Date],
		[Travel End Date],
		[Travel Start Date],
		[Advance Purchase Days],
		[Advance Purchase Window],
		[Ancillary Type],
		[Booking Method],
		[Is Active],
		[Itinerary Number],
		[Line Of Business],
		[Purchase Count],
		[Record Locator],
		[Special Request] AS [Special Request?],
		[Transaction Type],
		[Ticket Code],
		[Fare Rate Type],
		[Geography Type],
		[Vendor Name],
		[Location],
		[Credit Card BIN],
		[Credit Card Last 4 Digits],
		[Credit Card Type],
		[Invoice Number],
		[Transaction Amount GBP] AS [Transaction Amount(£)],
		[Policy Reason Description],
		[In Policy],
		[Policy Reason Code],
		[Meeting Attendee Traveller Group],
		[Meeting Name]
	FROM [Expenses].[tblTravelExpenses]
